INSERT INTO "clinics" ("id","name","city","address","phone","lat","lng","rating","reviews","specialties","about","created_at") VALUES ('shifa-family-clinic','{"en":"Shifa Family Clinic","ar":"عيادة الشفاء العائلية","ckb":"کلینیکی خێزانی شیفا"}'::jsonb,'erbil','{"en":"100m Street, Ankawa, Erbil","ar":"شارع 100 متر، عنكاوا، أربيل","ckb":"شەقامی ١٠٠ مەتری، عەنکاوە، هەولێر"}'::jsonb,'07730304703',36.238,43.993,4.8,214,'["general","pediatrics"]'::jsonb,'{"en":"A neighbourhood family practice for adults and children, with same-week appointments.","ar":"عيادة عائلية للكبار والأطفال مع مواعيد خلال الأسبوع نفسه.","ckb":"کلینیکێکی خێزانی بۆ گەورە و منداڵ، بە نۆرە لە هەمان هەفتەدا."}'::jsonb,timestamptz '2026-10-01 00:00:00+00' + interval '0 minutes') ON CONFLICT DO NOTHING;--> statement-breakpoint
