INSERT INTO "clinics" ("id","name","city","address","phone","lat","lng","rating","reviews","specialties","about","created_at") VALUES ('nabd-heart-center','{"en":"Nabd Heart Center","ar":"مركز نبض للقلب","ckb":"سەنتەری دڵی نەبز"}'::jsonb,'baghdad','{"en":"Al-Mansour, Baghdad","ar":"المنصور، بغداد","ckb":"مەنسوور، بەغدا"}'::jsonb,'07730304703',33.317,44.345,4.7,158,'["cardiology","general"]'::jsonb,'{"en":"Heart check-ups, ECG, and follow-up care with experienced cardiologists.","ar":"فحوصات القلب وتخطيط القلب والمتابعة مع أطباء قلب ذوي خبرة.","ckb":"پشکنینی دڵ، ئێ سی جی و چاودێری بەردەوام لەگەڵ پزیشکی دڵی بە ئەزموون."}'::jsonb,timestamptz '2026-10-01 00:00:00+00' + interval '2 minutes') ON CONFLICT DO NOTHING;--> statement-breakpoint
